/** Must match next.config.js's basePath. Next.js only auto-prefixes basePath onto
 * next/link, useRouter, Image, etc - plain fetch()/axios calls need it added manually,
 * or every request 404s once the app is served under a non-root path in production. */
export const BASE_PATH = (() => {
  const value = process.env.NEXT_PUBLIC_BASE_PATH;
  // Empty string is valid (app served from root); only an unset variable is an error.
  if (value === undefined) {
    throw new Error("Missing required environment variable: NEXT_PUBLIC_BASE_PATH");
  }
  return value;
})();

/** Strips a leading basePath segment from an href read directly off a DOM anchor's
 * `href` attribute - next/link bakes basePath into that attribute (see
 * node_modules/next/dist/client/link.js), but router.push()'s own basePath handling
 * (add-base-path.js) unconditionally re-prepends it with no "already has prefix" check,
 * so pushing an already-prefixed href double-prefixes it (/frontend/frontend/...) and
 * 404s. Only call this on hrefs sourced from the DOM; hrefs supplied by application code
 * as string literals (e.g. router.push("/lms-admin/users")) are already app-relative and
 * must NOT be passed through this. */
export function stripBasePath(href: string): string {
  if (!BASE_PATH) return href;
  if (href === BASE_PATH) return "/";
  if (href.startsWith(`${BASE_PATH}/`)) return href.slice(BASE_PATH.length);
  return href;
}
