import type { Role } from "@/types/auth";
import { ROLE_ADMIN, ROLE_CLIENT } from "@/permissions/roles";

export function hasRole(roles: readonly Role[] | undefined, role: Role): boolean {
  return !!roles && roles.includes(role);
}

export function canAccessAdmin(roles: readonly Role[] | undefined): boolean {
  return hasRole(roles, ROLE_ADMIN);
}

export function canAccessClient(roles: readonly Role[] | undefined): boolean {
  return hasRole(roles, ROLE_CLIENT);
}

/** Where a freshly-selected/known role should land the user. */
export function landingPathForRole(role: Role): string {
  return role === ROLE_ADMIN ? "/lms-admin" : "/lms-client";
}

// user_account.user_type_id: 1 = Super Admin, 2 = Admin (mirrors Login.java's
// `user_type_id == 1 || 2` checks). Several legacy screens (Department, Designation)
// give these two view-only access - CRUD is reserved for company-level admins/roles.
export const USER_TYPE_SUPER_ADMIN = 1;
export const USER_TYPE_ADMIN = 2;

/** True for the two platform-level user types that legacy restricts to view-only on
 * company-scoped screens like Department and Designation. */
export function isPlatformAdmin(userTypeId: number | undefined): boolean {
  return userTypeId === USER_TYPE_SUPER_ADMIN || userTypeId === USER_TYPE_ADMIN;
}

/** The Super Admin's own session only - not the Admin (2), and not a Super Admin session
 * switched into a company (that one carries user type 4). */
/** A platform admin's own session, or one switched into a company (userTypeId 4 - only ever
 * issued to a platform admin) - mirrors the backend's UserPrincipal#isPlatformAdminSession. */
export function isPlatformAdminSession(userTypeId: number | undefined): boolean {
  return isPlatformAdmin(userTypeId) || userTypeId === 4;
}

export function isSuperAdmin(userTypeId: number | undefined): boolean {
  return userTypeId === USER_TYPE_SUPER_ADMIN;
}
