import { NextRequest, NextResponse } from "next/server";
import {
  ACCESS_TOKEN_COOKIE,
  ACTIVE_ROLE_COOKIE,
  PREAUTH_TOKEN_COOKIE,
  REFRESH_TOKEN_COOKIE,
  REFRESH_TOKEN_MAX_AGE_SECONDS,
} from "@/lib/cookieNames";
import { decodeJwtPayload, isExpired, type DecodedJwtPayload } from "@/lib/jwt";
import { env } from "@/lib/env";
import { BASE_PATH } from "@/lib/basePath";
import { ROLE_ADMIN, ROLE_CLIENT } from "@/permissions/roles";
import { landingPathForRole } from "@/permissions/permissions";
import { forbidden, unauthorized } from "@/lib/apiErrors";

export const config = {
  matcher: [
    "/lms-admin/:path*",
    "/lms-client/:path*",
    "/select-role",
    "/verify-otp",
    "/change-password",
    "/license-update",
    "/privacy-consent",
    // The /api/proxy/** route handlers (lib/backendProxy.ts) only ever read whatever
    // access-token cookie is already on the request - without this, a background
    // fetch/axios call made after the access token expires mid-page (e.g. filling out a
    // long form) skips the proactive refresh below entirely, gets a 401 straight from
    // the expired-JWT check, and apiClient.ts's interceptor treats that as a real
    // session expiry and force-logs-out a still-legitimately-logged-in admin.
    "/api/proxy/:path*",
    // Same reason: this handler reads the role list straight off the access-token
    // cookie, which the browser drops the moment it expires (maxAge = expiresIn). A
    // "Switch to Admin/Client" click after sitting idle past that point otherwise
    // reaches the handler with no token at all and gets a 401 "You do not hold this
    // role", even though the refresh token is still perfectly valid.
    "/api/auth/select-role",
  ],
};

const isProduction = process.env.NODE_ENV === "production";

interface RefreshedTokens {
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
}

const REFRESH_TIMEOUT_MS = 8_000;

/**
 * Calls the Spring Boot backend directly (Edge runtime can't use axios, only fetch).
 * middleware.ts is the one place that proactively refreshes a near/already-expired
 * access token before a protected request ever reaches a page or API route.
 *
 * Native fetch has no default timeout, so an unreachable/slow backend would otherwise
 * hang every protected page load indefinitely - the AbortController bounds that.
 */
async function refreshTokens(refreshToken: string): Promise<RefreshedTokens | null> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REFRESH_TIMEOUT_MS);

  try {
    const response = await fetch(`${env.backendApiUrl}/api/auth/refresh`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ refreshToken }),
      signal: controller.signal,
    });
    if (!response.ok) {
      return null;
    }
    return (await response.json()) as RefreshedTokens;
  } catch {
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}

function clearAuthCookies(response: NextResponse): void {
  response.cookies.delete(ACCESS_TOKEN_COOKIE);
  response.cookies.delete(REFRESH_TOKEN_COOKIE);
  response.cookies.delete(ACTIVE_ROLE_COOKIE);
  response.cookies.delete(PREAUTH_TOKEN_COOKIE);
}

function setRefreshedCookies(response: NextResponse, tokens: RefreshedTokens): void {
  const base = { httpOnly: true, secure: isProduction, sameSite: "lax" as const, path: "/" };
  response.cookies.set(ACCESS_TOKEN_COOKIE, tokens.accessToken, { ...base, maxAge: tokens.expiresIn });
  response.cookies.set(REFRESH_TOKEN_COOKIE, tokens.refreshToken, {
    ...base,
    maxAge: REFRESH_TOKEN_MAX_AGE_SECONDS,
  });
}

/** setRefreshedCookies only updates the browser's cookies for *future* requests - the
 * request currently being handled was built from the original (expired) Cookie header,
 * and Route Handlers read it via next/headers's cookies(), which reflects that original
 * request, not this response's Set-Cookie. Without rewriting it here, the very request
 * that triggered the refresh still gets forwarded downstream with the stale access
 * token, producing exactly one spurious 401/"not authorized" right at the moment a
 * token lapses mid-session (e.g. mid-way through a long content-upload form) even
 * though the session is legitimately still active. */
function buildRefreshedRequestHeaders(request: NextRequest, tokens: RefreshedTokens): Headers {
  const headers = new Headers(request.headers);
  const kept = (headers.get("cookie") ?? "")
    .split(";")
    .map((entry) => entry.trim())
    .filter((entry) => entry && !entry.startsWith(`${ACCESS_TOKEN_COOKIE}=`) && !entry.startsWith(`${REFRESH_TOKEN_COOKIE}=`));
  kept.push(`${ACCESS_TOKEN_COOKIE}=${tokens.accessToken}`);
  kept.push(`${REFRESH_TOKEN_COOKIE}=${tokens.refreshToken}`);
  headers.set("cookie", kept.join("; "));
  return headers;
}

function isApiPath(pathname: string): boolean {
  return pathname.startsWith("/api/");
}

function requiredRoleForPath(pathname: string): "ADMIN" | "CLIENT" | null {
  if (pathname.startsWith("/lms-admin") || pathname.startsWith("/api/proxy/admin")) {
    return ROLE_ADMIN;
  }
  if (pathname.startsWith("/lms-client") || pathname.startsWith("/api/proxy/client")) {
    return ROLE_CLIENT;
  }
  return null; // e.g. /select-role - authenticated is enough, no specific role required
}

function hasRequiredRole(payload: DecodedJwtPayload | null, pathname: string): boolean {
  const required = requiredRoleForPath(pathname);
  if (!required) {
    return true;
  }
  return !!payload?.roles?.includes(required);
}

function redirectToLogin(request: NextRequest): NextResponse {
  const response = NextResponse.redirect(new URL(`${BASE_PATH}/login`, request.url));
  clearAuthCookies(response);
  return response;
}

/** An /api/proxy/** caller (axios/fetch) can't follow an HTML redirect the way a page
 * navigation can - it would just resolve with the login page's markup as a "200 OK" body
 * instead of a request it recognizes as unauthenticated. Route those callers to a plain
 * 401 JSON response instead, so apiClient.ts's interceptor sees the same "genuinely not
 * authenticated" signal it would from any other endpoint. */
function authFailureResponse(request: NextRequest): NextResponse {
  if (isApiPath(request.nextUrl.pathname)) {
    const response = unauthorized("Not authenticated", request.nextUrl.pathname);
    clearAuthCookies(response);
    return response;
  }
  return redirectToLogin(request);
}

/** /verify-otp needs a "2FA" preauth token, /change-password needs "PASSWORD_CHANGE",
 * /license-update needs "LICENSE_UPDATE", /privacy-consent needs "CONSENT" - none of these
 * are role-protected areas, all four require the narrowly-scoped preauth token issued by a
 * pending login instead of full access/refresh tokens. */
function requiredPreAuthPurpose(
  pathname: string,
): "2FA" | "PASSWORD_CHANGE" | "LICENSE_UPDATE" | "CONSENT" | null {
  if (pathname === "/verify-otp") {
    return "2FA";
  }
  if (pathname === "/change-password") {
    return "PASSWORD_CHANGE";
  }
  if (pathname === "/license-update") {
    return "LICENSE_UPDATE";
  }
  if (pathname === "/privacy-consent") {
    return "CONSENT";
  }
  return null;
}

export async function middleware(request: NextRequest): Promise<NextResponse> {
  const { pathname } = request.nextUrl;

  const preAuthPurpose = requiredPreAuthPurpose(pathname);
  if (preAuthPurpose) {
    const preAuthToken = request.cookies.get(PREAUTH_TOKEN_COOKIE)?.value;
    const payload = preAuthToken ? decodeJwtPayload(preAuthToken) : null;
    if (!preAuthToken || !payload || isExpired(payload) || payload.purpose !== preAuthPurpose) {
      return redirectToLogin(request);
    }
    return NextResponse.next();
  }

  const accessToken = request.cookies.get(ACCESS_TOKEN_COOKIE)?.value;
  const refreshToken = request.cookies.get(REFRESH_TOKEN_COOKIE)?.value;

  if (!accessToken && !refreshToken) {
    return authFailureResponse(request);
  }

  let payload = accessToken ? decodeJwtPayload(accessToken) : null;
  let freshTokens: RefreshedTokens | null = null;

  if (!accessToken || isExpired(payload)) {
    if (!refreshToken) {
      return authFailureResponse(request);
    }
    freshTokens = await refreshTokens(refreshToken);
    if (!freshTokens) {
      return authFailureResponse(request);
    }
    payload = decodeJwtPayload(freshTokens.accessToken);
  }

  if (!hasRequiredRole(payload, pathname)) {
    if (isApiPath(pathname)) {
      const response = forbidden("Not authorized for this role", pathname);
      if (freshTokens) {
        setRefreshedCookies(response, freshTokens);
      }
      return response;
    }
    // Authenticated, just not for this section - send them to a portal they do hold.
    const fallbackRole = payload?.roles?.includes(ROLE_ADMIN) ? ROLE_ADMIN : ROLE_CLIENT;
    const response = NextResponse.redirect(new URL(`${BASE_PATH}${landingPathForRole(fallbackRole)}`, request.url));
    if (freshTokens) {
      setRefreshedCookies(response, freshTokens);
    }
    return response;
  }

  const response = freshTokens
    ? NextResponse.next({ request: { headers: buildRefreshedRequestHeaders(request, freshTokens) } })
    : NextResponse.next();
  if (freshTokens) {
    setRefreshedCookies(response, freshTokens);
  }
  return response;
}
