import { NextResponse } from "next/server";
import type { ApiErrorResponse } from "@/types/api";

/** Builds the same ApiErrorResponse shape the backend uses, for validation failures
 * that happen inside our own Route Handlers before a backend call is even made. */
export function badRequest(message: string, path: string): NextResponse<ApiErrorResponse> {
  return NextResponse.json(
    {
      timestamp: new Date().toISOString(),
      status: 400,
      error: "Bad Request",
      message,
      path,
    },
    { status: 400 },
  );
}

export function unauthorized(message: string, path: string): NextResponse<ApiErrorResponse> {
  return NextResponse.json(
    {
      timestamp: new Date().toISOString(),
      status: 401,
      error: "Unauthorized",
      message,
      path,
    },
    { status: 401 },
  );
}

export function forbidden(message: string, path: string): NextResponse<ApiErrorResponse> {
  return NextResponse.json(
    {
      timestamp: new Date().toISOString(),
      status: 403,
      error: "Forbidden",
      message,
      path,
    },
    { status: 403 },
  );
}

/** Used when the backend itself can't be reached/times out, so the browser gets a
 * fast, clear error instead of a route handler hanging or crashing with a generic 500. */
export function serviceUnavailable(path: string): NextResponse<ApiErrorResponse> {
  return NextResponse.json(
    {
      timestamp: new Date().toISOString(),
      status: 503,
      error: "Service Unavailable",
      message: "Could not reach the K-nest LMS backend. Please try again shortly.",
      path,
    },
    { status: 503 },
  );
}
