/**
 * Minimal base64url JWT payload decoder - no signature verification. This is safe
 * because the token's validity is always ultimately enforced by the backend on every
 * real API call; this decode is only used (in middleware.ts, Edge runtime) as an
 * optimization to avoid unnecessary requests, never as the actual security boundary.
 * Written with only Web APIs (atob) so it also runs in the Edge runtime.
 */
export interface DecodedJwtPayload {
  sub?: string;
  exp?: number;
  iat?: number;
  userId?: number;
  companyId?: number;
  loginId?: string;
  roles?: string[];
  type?: string;
  /** user_account.user_type_id - see SecurityConstants.CLAIM_USER_TYPE_ID (Java). */
  userTypeId?: number;
  /** user_account.department_id, absent when the user isn't assigned to one. */
  departmentId?: number;
  /** Present on preauth tokens only - "2FA" or "PASSWORD_CHANGE" (see SecurityConstants.java). */
  purpose?: string;
}

export function decodeJwtPayload(token: string): DecodedJwtPayload | null {
  try {
    const parts = token.split(".");
    const payloadPart = parts[1];
    if (parts.length !== 3 || !payloadPart) {
      return null;
    }

    const base64 = payloadPart.replace(/-/g, "+").replace(/_/g, "/");
    const paddingNeeded = (4 - (base64.length % 4)) % 4;
    const padded = base64 + "=".repeat(paddingNeeded);

    const binary = atob(padded);
    const utf8Json = decodeURIComponent(
      Array.from(binary)
        .map((char) => "%" + char.charCodeAt(0).toString(16).padStart(2, "0"))
        .join(""),
    );

    return JSON.parse(utf8Json) as DecodedJwtPayload;
  } catch {
    return null;
  }
}

/** True if the token is missing/unparseable/expired (with a small safety skew). */
export function isExpired(payload: DecodedJwtPayload | null, skewSeconds = 10): boolean {
  if (!payload || typeof payload.exp !== "number") {
    return true;
  }
  const nowSeconds = Date.now() / 1000;
  return payload.exp <= nowSeconds + skewSeconds;
}
