/**
 * Plain string constants only - no next/headers import here, so this module is safe
 * to import from Client Components too (lib/cookies.ts itself is server-only).
 */
export const ACCESS_TOKEN_COOKIE = "kn_access_token";
export const REFRESH_TOKEN_COOKIE = "kn_refresh_token";
export const ACTIVE_ROLE_COOKIE = "kn_active_role";

/**
 * The JWT only carries userId/loginId/companyId/roles (see JwtTokenProvider.java) - no
 * fullName or mustChangePassword. Those two non-sensitive fields are cached here at
 * login time so GET /api/auth/me can rebuild a full profile without another backend
 * call. Not httpOnly: it's not a secret, just display data.
 */
export const PROFILE_COOKIE = "kn_profile";

/**
 * Holds the short-lived preauth token issued instead of full tokens when a login
 * resolves to OTP_REQUIRED or PASSWORD_CHANGE_REQUIRED (see LoginStatus.java). httpOnly
 * for the same reason the access/refresh tokens are - it's a bearer credential, even
 * though a narrowly-scoped one.
 */
export const PREAUTH_TOKEN_COOKIE = "kn_preauth_token";

export const REFRESH_TOKEN_MAX_AGE_SECONDS = 60 * 60 * 24 * 7; // mirrors backend default (7 days)
export const PREAUTH_TOKEN_MAX_AGE_SECONDS = 60 * 10; // mirrors backend default (10 minutes)
