/** Server-only environment access. Never import this from a Client Component. */

/** Required values have no fallback: a missing one fails loudly instead of silently
 * running degraded. next.config.js also checks the secrets when the server starts. */
function requiredSecret(name: string): string {
  const value = process.env[name];
  if (!value || value.trim().length === 0) {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value.trim();
}

export const env = {
  /** Not a secret - where this server reaches the backend. Set in .env only (no hardcoded
   * fallback); read lazily so importing this module never throws by itself. */
  get backendApiUrl(): string {
    return requiredSecret("BACKEND_API_URL");
  },
  /** Must match the backend's app.security.client-ip.bff-secret (BFF_SHARED_SECRET) - see
   * lib/clientIp.ts. Read lazily so a Client Component bundle never evaluates it. */
  get bffSharedSecret(): string {
    return requiredSecret("BFF_SHARED_SECRET");
  },
};
